Here is the problem description:
<problem_description>
Mr. Chanek has an integer represented by a string $$$s$$$. Zero or more digits have been erased and are denoted by the character _. There are also zero or more digits marked by the character X, meaning they're the same digit.Mr. Chanek wants to count the number of possible integer $$$s$$$, where $$$s$$$ is divisible by $$$25$$$. Of course, $$$s$$$ must not contain any leading zero. He can replace the character _ with any digit. He can also replace the character X with any digit, but it must be the same for every character X.As a note, a leading zero is any 0 digit that comes before the first nonzero digit in a number string in positional notation. For example, 0025 has two leading zeroes. An exception is the integer zero, (0 has no leading zero, but 0000 has three leading zeroes).
</problem_description>

Here is the Java 11 code you have to repair:
<original_code>
import java.io.*;
import java.util.*;

public final class Solution {

  static BufferedReader br = new BufferedReader(new InputStreamReader(System.in));
  static BufferedWriter bw = new BufferedWriter(new OutputStreamWriter(System.out));
  static StringTokenizer st;

  static class Rec {
    int a;
    int b;
    long c;
    Rec(int a, int b, long c) { this.a = a; this.b = b; this.c = c; }
  }

  static class Pair<F, S> {
    F a;
    S b;
    Pair(F a, S b) { this.a = a; this.b = b; }
  }

  static class SortByFirst implements Comparator<Pair<Integer, Integer>> {
    @Override
    public int compare(Pair<Integer, Integer> p1, Pair<Integer, Integer> p2) {
      return Integer.compare(p1.a, p2.a);
    }
  }

  static int modAdd(int a, int b, int mod) {
    return (a % mod + b % mod) % mod;
  }

  static int modSub(int a, int b, int mod) {
    return (int) ((1L * (a % mod) - 1L * (b % mod) + mod) % mod);
  }

  static int modMul(int a, int b, int mod) {
    return (int) ((1L * (a % mod) * (b % mod)) % mod);
  }

  static int modPow(int base, int exp, int mod) {
    if (exp == 0) return 1;
    if (exp == 1) return base % mod;
    int half = modPow(base, exp / 2, mod);
    int res = modMul(half, half, mod);
    return (exp % 2 == 1) ? modMul(res, base, mod) : res;
  }

  static int modDiv(int a, int b, int mod) {
    return modMul(a, modPow(b, mod - 2, mod), mod);
  }

  static int gcd(int a, int b) {
    while (b != 0) {
      int t = b;
      b = a % b;
      a = t;
    }
    return a;
  }

  static int binarySearchLeftmost(int target, int[] arr) {
    int lo = 0, hi = arr.length - 1, ans = -1;
    while (lo <= hi) {
      int mid = lo + (hi - lo) / 2;
      if (arr[mid] < target) {
        ans = mid;
        lo = mid + 1;
      } else {
        hi = mid - 1;
      }
    }
    return ans;
  }

  static long[] logSeries(long base, long n) {
    long i = 1, sum = 0;
    int count = 0;
    long[] res = new long[2];
    while (i < base) {
      sum += i;
      count++;
      if (sum == n) {
        res[0] = count;
        res[1] = sum;
        return res;
      }
      i *= 2;
    }
    res[0] = count;
    res[1] = sum;
    return res;
  }

  static void increment(Map<Integer, Integer> map, int key) {
    map.merge(key, 1, Integer::sum);
  }

  static long sumList(List<Long> list) {
    long total = 0;
    for (long x : list) total += x;
    return total;
  }

  static int charToIndex(char c) {
    return c - 'a';
  }

  static int binarySearchEqual(int[] prefix, int start, int target) {
    int lo = start + 1, hi = prefix.length - 1, ans = 0;
    while (lo <= hi) {
      int mid = lo + (hi - lo) / 2;
      int diff = prefix[mid] - prefix[start];
      if (diff == target) return mid;
      if (diff < target) {
        ans = mid;
        lo = mid + 1;
      } else {
        hi = mid - 1;
      }
    }
    return ans;
  }

  static Pair<Long, Integer> analyze(List<Integer> nums) {
    long sum = 0;
    int minVal = Integer.MAX_VALUE;
    for (int x : nums) {
      sum += x;
      minVal = Math.min(minVal, x);
    }
    return new Pair<>(sum - minVal, minVal);
  }

  static int findMaxDivisor(Map<Integer, Integer> map, int n, int targetCount) {
    int maxDiv = 0;
    for (int i = 1; i * i <= n; i++) {
      if (n % i == 0) {
        if (i != n / i) {
          if (map.getOrDefault(n / i, 0) == targetCount) maxDiv = Math.max(maxDiv, n / i);
        }
        if (map.getOrDefault(i, 0) == targetCount) maxDiv = Math.max(maxDiv, i);
      }
    }
    return maxDiv;
  }

  static List<Integer> getKeys(Map<Integer, Integer> map) {
    return new ArrayList<>(map.keySet());
  }

  static List<Integer> getValues(Map<Integer, Integer> map) {
    return new ArrayList<>(map.values());
  }

  static int findMax(List<Integer> list) {
    int max = list.get(0);
    for (int x : list) max = Math.max(max, x);
    return max;
  }

  static int findMin(List<Integer> list) {
    int min = list.get(0);
    for (int x : list) min = Math.min(min, x);
    return min;
  }

  static final int[][] DIRS = {{-1,0},{0,1},{1,0},{0,-1}};

  public static void main(String[] args) throws IOException {
    String s = br.readLine();
    int n = s.length();

    if (n == 1 && (s.charAt(0) == '0' || s.charAt(0) == '_' || s.charAt(0) == 'X')) {
      bw.write("1\n");
    } else if (n == 1) {
      bw.write("0\n");
    } else if (s.charAt(0) == '0') {
      bw.write("0\n");
    } else {
      String[] endings = {"25", "50", "75", "00"};
      String[] wildcards = {"__", "_X", "X_", "XX"};
      int[] baseWays = {4, 4, 4, 1};
      baseWays[1] = s.charAt(0) == 'X' ? 2 : 4;
      baseWays[2] = s.charAt(0) == 'X' ? 3 : 4;
      baseWays[0] = n == 2 ? 3 : 4;
      baseWays[1] = n == 2 ? 3 : 4;

      int ways = 0;
      String lastTwo = s.substring(n - 2);
      for (int i = 0; i < 4; i++) {
        if (lastTwo.equals(endings[i])) {
          ways = 1;
          break;
        }
      }

      if (ways == 0) {
        if (lastTwo.charAt(0) == '_' || lastTwo.charAt(0) == 'X') {
          ways = 2;
          if (lastTwo.charAt(1) == '0' && s.charAt(0) == 'X') ways = 1;
        } else if (lastTwo.charAt(1) == '_' || lastTwo.charAt(1) == 'X') {
          ways = 1;
        } else {
          for (int i = 0; i < 4; i++) {
            if (lastTwo.equals(wildcards[i])) {
              ways = baseWays[i];
              break;
            }
          }
        }
      }

      if (lastTwo.equals("XX") && s.charAt(0) == 'X') ways = 0;

      if (ways > 0) {
        char c0 = lastTwo.charAt(0);
        char c1 = lastTwo.charAt(1);
        if (c0 != '2' && c0 != '5' && c0 != '7' && c0 != '0' && c0 != 'X' && c0 != '_') ways = 0;
        if (c1 != '0' && c1 != '5' && c1 != 'X' && c1 != '_') ways = 0;
      }

      int xways = 1;
      if (ways > 0) {
        if (lastTwo.charAt(0) == 'X') xways = baseWays[2];
        else if (lastTwo.charAt(1) == 'X') xways = baseWays[1] / 2;
        else xways = (s.charAt(0) == 'X') ? 9 : 10;
      }

      long multiplier = 1;
      boolean hasX = false;
      for (int i = 0; i < n - 2; i++) {
        if (s.charAt(i) == 'X') hasX = true;
        if (s.charAt(i) == '_') {
          multiplier *= (i == 0) ? 9 : 10;
        }
      }
      if (hasX && ways > 0) multiplier *= xways;
      multiplier *= ways;

      bw.write(Long.toString(multiplier) + "\n");
    }
    bw.flush();
  }
}
